-- ------------------------------------------------------------------------------
-- Cập nhật Sequence tự tăng (SERIAL) cho tất cả các bảng sau khi nạp ID tĩnh
-- ------------------------------------------------------------------------------
SELECT setval(pg_get_serial_sequence('subjects', 'id'), coalesce(max(id), 1)) FROM "subjects";
SELECT setval(pg_get_serial_sequence('subject_groups', 'id'), coalesce(max(id), 1)) FROM "subject_groups";
SELECT setval(pg_get_serial_sequence('universities', 'id'), coalesce(max(id), 1)) FROM "universities";
SELECT setval(pg_get_serial_sequence('majors', 'id'), coalesce(max(id), 1)) FROM "majors";
SELECT setval(pg_get_serial_sequence('university_majors', 'id'), coalesce(max(id), 1)) FROM "university_majors";
SELECT setval(pg_get_serial_sequence('admission_scores', 'id'), coalesce(max(id), 1)) FROM "admission_scores";
SELECT setval(pg_get_serial_sequence('major_embeddings', 'id'), coalesce(max(id), 1)) FROM "major_embeddings";

COMMIT;
