INSERT INTO "major_embeddings" ("id", "major_id", "description", "embedding") VALUES
  (1,1,'Ngành Giáo dục học là lĩnh vực khoa học nghiên cứu sâu rộng về quá trình dạy và học, đòi hỏi người học sở hữu tư duy logic sắc bén để phân tích các *lý luận dạy học* và sự sáng tạo không ngừng trong *phát triển chương trình*. Tố chất giao tiếp xã hội, thấu cảm là cực kỳ quan trọng để hiểu và tương tác hiệu quả với người học. Kỹ năng thiết kế các hoạt động học tập, ứng dụng *công nghệ giáo dục* và thực hiện *đánh giá giáo dục* là cần thiết. Môi trường làm việc đa dạng, từ văn phòng để xây dựng chính sách, lên kế hoạch cho đến các cơ sở giáo dục để triển khai và quan sát, thường đòi hỏi khả năng làm việc nhóm chặt chẽ trong các dự án *nghiên cứu giáo dục* và đôi khi đối mặt với áp lực cao khi đổi mới phương pháp. Sinh viên còn được trang bị kiến thức vững chắc về *tâm lý học sư phạm* để tối ưu hóa trải nghiệm học tập.','[-0.10357849,-0.066791564,0.13150917,-0.09839254,-0.20298545,-0.04353272,0.04703638,-0.09485514,0.06696661,-0.20586388,-0.12823555,-0.026879532,0.19002557,-0.35041898,0.08794879,0.83291817,-0.2604742,0.24140099,-0.046512518,-0.13896802,0.1519337,-0.12997337,-0.16785812,0.12737662,-0.05262985,-0.14452298,-0.15721872,-0.14241612,0.08335981,-0.448348,-0.06705236,0.11105711,-0.13243616,0.14809234,0.036926623,0.121087104,-0.15910254,0.1890405,0.34012365,0.007848277,0.050046522,0.07634086,-0.08877388,0.21727662,-0.08142204,0.27681977,-0.07694609,0.17331928,0.29326734,0.11488981,0.24148738,0.10536163,-0.26791352,0.12578295,-0.26038322,-0.060284227,0.01917215,-0.068326294,0.16918595,0.23064081,-0.118687645,-0.084485635,0.013559456,0.1670648,0.3484638,-0.0991119,-0.12388497,-0.21114598,-0.036616478,-0.09521699,0.25358444,-0.061677303,-0.27667782,-0.24509406,-0.20995763,-0.045108777,-0.03409588,0.3098146,0.0629827,0.046188965,-0.107868746,0.18736885,-0.14911051,0.14635423,-0.1392475,0.06792579,0.14892548,-0.104564995,-0.014692267,-0.25848734,-0.0441192,0.23682576,0.35399714,-0.046669118,-0.018927287,0.21206033,-0.08453529,-0.10890534,-0.026949918,-0.3454