INSERT INTO "major_embeddings" ("id", "major_id", "description", "embedding") VALUES
  (101,101,'Ngành Ngôn ngữ Hàn Quốc đòi hỏi người học sở hữu tư duy logic nhạy bén, khả năng phân tích ngữ pháp sâu sắc và sự tỉ mỉ trong việc nắm bắt các sắc thái văn hóa ẩn chứa trong từng từ vựng. Bên cạnh đó, tố chất giao tiếp xã hội tốt là yếu tố then chốt để xây dựng mối quan hệ hiệu quả, đặc biệt khi làm việc trong môi trường quốc tế năng động. Kỹ năng dịch thuật chuyên nghiệp, khả năng biên phiên dịch song ngữ, và kiến thức về văn hóa, xã hội Hàn Quốc là những kỹ năng cứng cần được trau dồi. Sự sáng tạo trong cách truyền đạt thông tin, khả năng làm việc nhóm và chịu áp lực cao là những kỹ năng mềm quan trọng. Người theo ngành này có thể làm việc trong các công ty đa quốc gia, tổ chức giáo dục, viện nghiên cứu, lĩnh vực du lịch lữ hành, hoặc ngành công nghiệp giải trí, nơi đòi hỏi sự linh hoạt và khả năng thích ứng cao. Các vị trí như chuyên viên xuất nhập khẩu, biên dịch viên, phiên dịch viên, hướng dẫn viên du lịch, hay chuyên viên truyền thông đều mở ra cơ hội phát triển rộng lớn.','[0.04989122,0.29843783,0.037654296,0.0131187225,-0.23306634,-0.04887206,0.04280181,-0.1049837,-0.16109377,-0.2906773,-0.07749109,0.1728217,-0.1523028,-0.15073833,-0.35885406,0.05177372,-0.19653958,0.22455567,-0.017759131,0.013142353,-0.41695,-0.036701072,0.18693414,-0.09733925,-0.26747665,0.27390337,0.0036248101,-0.15107605,0.17029575,0.047627676,0.047670253,-0.0088720145,0.048750535,0.12921825,0.1438099,0.042766716,-0.1574535,0.18489021,-0.0774263,-0.07190465,-8.4937084e-05,0.020999387,0.16905639,0.18438429,0.26172146,-0.1201399,-0.017832642,0.07978886,0.08570598,0.26086408,-0.08902861,0.054424904,-0.24634291,-0.10023418,-0.037112825,0.1837826,0.12917864,0.11149786,0.20065558,-0.19061717,0.31793594,-0.12171582,0.16928458,0.2324996,0.22315575,-0.19328436,0.15843421,-0.040597722,-0.24881835,-0.006109014,0.27111822,-0.17304933,-0.14012845,-0.32524684,-0.11008312,-0.224567,-0.07616426,0.23830692,0.011110683,0.04449301,0.10255808,-0.33933258,0.10383402,0.12399017,0.07387611,0.21806