INSERT INTO "major_embeddings" ("id", "major_id", "description", "embedding") VALUES
  (201,201,'Theo đuổi Khoa học môi trường đồng nghĩa với việc bạn cần trang bị tư duy hệ thống mạnh mẽ, tính cẩn thận và sự nhạy bén trước các vấn đề xã hội. Khối kỹ năng đặc thù bao gồm năng lực đánh giá rủi ro sinh thái, phân tích chỉ tiêu hóa lý và ứng dụng hệ thống thông tin địa lý vào quy hoạch. Không gian làm việc của ngành liên tục luân chuyển giữa cơ quan quản lý nhà nước, tổ chức phi chính phủ và các khu vực thực địa lấy mẫu. Quá trình tác nghiệp yêu cầu sự am hiểu sâu sắc về ô nhiễm không khí, xử lý chất thải, đánh giá tác động môi trường, phát triển bền vững, biến đổi khí hậu và công nghệ sinh thái. Ngành học này dành riêng cho những người muốn cống hiến trí tuệ để duy trì một hành tinh xanh sạch.','[-0.10440493,-0.03757263,-0.093067504,0.112335436,-0.024673384,0.012050792,-0.061294578,-0.21302614,0.20796542,-0.20084181,0.19252297,-0.050935887,-0.0076367385,-0.47096846,-0.0017196976,0.15976886,-0.016959943,0.2687469,0.15311652,-0.047154475,-0.08265022,-0.002521325,0.038296197,0.0008320652,-0.18522884,-0.027186872,-0.06895841,0.13445649,0.07363822,-0.049845334,-0.10899662,0.011914858,0.004119403,-0.17493385,0.2744039,0.054844778,-0.1771008,-0.10229023,0.12304596,-0.2668488,-0.23136723,0.24345574,-0.07530377,-0.010194502,-0.1336068,0.04413191,-0.030057464,0.03812884,0.07009488,0.0019180976,0.07943726,0.25304347,-0.1717546,0.14672695,-0.21810897,0.04046274,0.17755269,-0.0594756,0.21855822,0.30746508,0.047998484,-0.016500302,-0.016413875,0.16370082,0.06415386,-0.020830538,-0.2291285,-0.09497115,-0.0734542,0.04498823,-0.098659284,0.32124746,-0.03646233,0.008094308,-0.29642883,0.09595844,-0.1096423,0.2690482,0.12688202,-0.015152957,-0.1275755,-0.2992415,-0.080106415,0.048108667,-0.1529358,-0.026703814,0.05429323,0.031439256,0.11517776,0.009390162,0.03664912,0.043042235,0.15185738,-0.05027003,-0.093215235,0.031592112,0.07540596,-0.0037379977,-0.032809954,-0.12001048,0.060883798,0.09045684,0.12466462,0.0077518662,-0.042035457,-0.24307804,0.079087906,0.13139977,-0