INSERT INTO "major_embeddings" ("id", "major_id", "description", "embedding") VALUES
  (301,301,'Ngành Đô thị học tìm kiếm những cá nhân có tầm nhìn vĩ mô bao quát, tư duy phân tích xã hội sắc bén và khả năng thấu cảm với các vấn đề của cộng đồng. Người học sẽ được rèn luyện kỹ năng phân tích dữ liệu không gian, đánh giá chính sách công và quy hoạch mạng lưới dịch vụ xã hội. Không gian làm việc thường là các viện nghiên cứu phát triển, cơ quan quản lý nhà nước hoặc các tổ chức phi chính phủ về phát triển bền vững. Chuyên môn của bạn gắn bó với các khái niệm như đô thị hóa, không gian công cộng, xã hội học đô thị, chính sách công, phát triển bền vững và tái thiết đô thị. Đây là ngành học đa diện, giúp bạn giải mã cấu trúc vận hành của các siêu đô thị và đề xuất giải pháp nhằm nâng cao chất lượng sống cho cư dân thành thị.','[0.0051844344,0.039187137,0.0036972684,0.12112419,-0.026364356,-0.048172854,0.23008618,-0.31883284,0.0887105,-0.44677204,0.055939734,0.00038692626,-0.044396386,-0.3038484,0.009010009,-0.07577989,-0.06806394,0.24722037,-0.12914415,-0.018173328,-0.113803096,-0.13473982,0.2051103,-0.2143819,-0.09167679,-0.0765037,-0.0734819,0.16519034,0.10370356,-0.14319427,0.14904967,-0.009459326,-0.12220662,0.18482426,0.23838824,-0.13319845,-0.21589456,0.0262639,0.17490491,-0.21192785,-0.058056872,0.1709981,0.057201415,0.1736109,-0.13520992,0.18275447,0.048706688,0.06652383,0.42409822,0.0743871,0.18609941,-0.05491821,-0.25061497,-0.045245264,-0.33947802,0.046492424,0.031491898,-0.14095083,0.2977189,0.21030787,0.15169778,-0.24088532,0.10426822,0.3102105,0.18079682,-0.018102983,0.18019496,-0.2399664,-0.24899992,0.14348798,-0.0013553434,-0.060060263,0.043843403,0.16974305,-0.2704386,-0.038586732,0.21598086,0.0726124,0.2192566,0.008819707,-0.004810767,0.039105624,0.100056,-0.26897398,-0.11796598,0.26675758,0.006187194,-0.10570079,0.19205546,0.0036364433,-0.053996477,0.0741378,0.086330995,0.13181338,-0.022099396,0.08867335,-0.017201854,-0.11162836,-0.021440597,-0.036236778,0.16462515,0.28445548,0.22542062,-0.05182186,-0.041897405,-0.20862469,0.065336965