INSERT INTO "major_embeddings" ("id", "major_id", "description", "embedding") VALUES
  (402,402,'Ngành này tìm kiếm những cá nhân có thể lực dẻo dai, tư duy cơ học nhạy bén và tinh thần quả cảm khi điều khiển những cỗ máy chiến tranh khổng lồ. Sinh viên được huấn luyện kỹ năng lái xe tăng địa hình, xạ kích pháo tăng và chỉ huy đội hình mũi nhọn đột kích. Không gian làm việc chủ yếu là thao trường huấn luyện, các lữ đoàn xe tăng thiết giáp cơ động hoặc xưởng bảo dưỡng vũ khí hạng nặng. Hành trang chuyên môn bao hàm các khái niệm như chiến thuật tăng thiết giáp, hỏa lực pháo tăng, mũi nhọn đột kích, xe thiết giáp, hiệp đồng cơ giới và hệ thống truyền động. Sĩ quan thiết giáp là những người dẫn đầu đội hình, tạo ra sức mạnh đột phá không thể cản phá để thọc sâu, chia cắt và tiêu diệt trận địa đối phương.','[-0.0873132,-0.12780535,0.03701545,0.07070483,0.03848074,0.19060354,-0.26045337,-0.054362625,-0.21354571,-0.2956297,-0.18822089,0.20686232,0.18216132,-0.24672307,0.004598666,0.09045342,0.03071478,0.11864717,-0.153727,0.17362757,0.26994932,-0.17261116,0.38779837,-0.10188638,-0.1810142,-0.029344162,0.24859795,0.2853486,0.024043553,-0.2293712,0.17725857,-0.15205863,0.10075956,-0.12262966,0.2648189,-0.0326906,-0.12716138,0.24069895,-0.0050898916,0.32794663,0.1167668,0.11153154,-0.07683256,0.03713212,-0.04665243,0.24759097,0.21627113,0.17664412,0.355913,0.16159055,-0.059566885,0.054678854,-0.2547874,0.036193594,-0.14398439,0.3909119,0.0025883033,0.07388252,0.24000666,-0.11064532,0.1415745,-0.19496226,0.15632406,0.14601949,0.09507605,-0.41895473,0.079358615,-0.18246968,-0.01412017,0.042910893,0.122767195,-0.14965957,-0.05631078,0.064176925,-0.019100849,0.032759245,0.1199619,-0.088814355,0.102500476,0.11739674,-0.14650004,-0.28489065,-0.05310781,-0.29558092,-0.1065476,0.038825627,0.08909442,-0.12213987,-0.021351034,-0.2379417,0.11204526,0.07245859,0.25401545,0.14952734,0.014615588,0.20802437,0.16608307,-0.047988277,0.1474922,-0.37154943,0.08607755,0.13402352,0.019155964,-0.20253074,-0.27008387,-0.3116355,-0.018021898,0.01907103,0.01845727,-0.15642482,0.0063